      knuth_bendix::add_generating_pair(kb, "T", "");
      knuth_bendix::add_generating_pair(kb, "u", "");
      knuth_bendix::add_generating_pair(kb, "U", "");
      knuth_bendix::add_generating_pair(kb, "l", "");
      knuth_bendix::add_generating_pair(kb, "L", "");

