    presentation::add_rule(p, "aaBab"s, "");
    presentation::add_rule(p, "AbbbCac"s, "");
    presentation::add_rule(p, "AbccaBc"s, "");

    using RewritingSystem = detail::RewritingSystemTrie<LenLexCmp>;
